var e=[{id:`n_1`,type:`scene_change`,speaker:null,text:null,stage:{bg:`CHURCH`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:null,R:null}}},{id:`n_2`,type:`dialog`,speaker:`LAURA_STREGA_WEDDING_NULL`,text:{KOREA:`우리 카페 바보들이랑 다르게 머리를 쓸 줄 아네. 잠든 마녀를 깨워 혼약을 맺고, 악랄한 종신 계약서에 사인할 망령을 함께 찾아 나선다는 계획이라. 그 선택, 마음에 들어.`,JPN:`妾のカフェのバカたちとは違って頭を使う方法を知っているな。眠った魔女を起こして婚約をし、あくどい終身契約書にサインする亡霊を一緒に探し出そうという計画か。その選択、気に入ったぞ。`,ENG:`You’re pretty smart, unlike the dummies in my cafe. So your plan is to wake a sleeping witch, get engaged, and look for a ghost to sign the shady lifetime contract for you? I like that.`,TWN:`你和我們咖啡廳裡那些傻瓜不一樣，你會用腦袋呢？喚醒沉睡的魔女締結婚約，再一起尋找會在狠毒的終身契約上簽約的鬼。這計劃，我喜歡。`},stage:{bg:`CHURCH`,bg_animation:null,bgm:`CUTSCENE_HOPE`,filter:`NCFT_NORMAL`,slots:{L:null,C:{char_id:`LAURA_STREGA_WEDDING_NULL`,face:`UNIT_LAUGH`,hologram:!1},R:null}}}];export{e as default};